//! The Latin model, generated by flexion-train from configs/src/latin.rs: one
//! module per part of speech (and per helper model), each a
//! [`flexion::PosModel`]. Don't edit by hand.

use flexion::{Model, PosModel, Spelling, SpellingStrings};

mod noun;
mod adjective;
mod verb;
mod pronoun;
mod numeral;
mod noun_restore;
mod noun_restore_front;
mod adjective_restore;
mod adjective_restore_front;
mod verb_restore;
mod verb_restore_front;
mod pronoun_restore;
mod numeral_restore;

static STRINGS: SpellingStrings<'static> = SpellingStrings {
    stress_marks: "",
    stress_table: "",
    vowels: "aeiouyāēīōūȳ",
    implicit: "",
    fold_from: "āēīōūȳj",
    fold_to: "aeiouyi",
    strip_marks: "\u{306}\u{304}",
    unmark_from: "āēīōūȳ",
    unmark_to: "aeiouy",
    syllabic: "",
    mute: "",
    diphthongs: "",
    hiatus: "",
};

/// The model, in the config's order of parts of speech (helper models
/// after).
pub(crate) fn build() -> Model<'static> {
    Model::new(
        Spelling::new(true, false, STRINGS),
        vec![
            &noun::Noun as &dyn PosModel,
            &adjective::Adjective as &dyn PosModel,
            &verb::Verb as &dyn PosModel,
            &pronoun::Pronoun as &dyn PosModel,
            &numeral::Numeral as &dyn PosModel,
            &noun_restore::NounRestore as &dyn PosModel,
            &noun_restore_front::NounRestoreFront as &dyn PosModel,
            &adjective_restore::AdjectiveRestore as &dyn PosModel,
            &adjective_restore_front::AdjectiveRestoreFront as &dyn PosModel,
            &verb_restore::VerbRestore as &dyn PosModel,
            &verb_restore_front::VerbRestoreFront as &dyn PosModel,
            &pronoun_restore::PronounRestore as &dyn PosModel,
            &numeral_restore::NumeralRestore as &dyn PosModel,
        ],
    )
}
